import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as s}from"./chunks/OFF.BrU7kQE-.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as a}from"./chunks/EN.P9aPnFBv.js";import{_ as r,a as o,b as n}from"./chunks/M-S-LCS11a.DEHuJb6u.js";import{_ as l,o as d,c as p,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const A=JSON.parse('{"title":"Paramètres moins courants","description":"","frontmatter":{"source_hash":"702fd175c0","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/use/lesscommon.md","filePath":"fr/use/lesscommon.md"}'),c={name:"fr/use/lesscommon.md"};function u(v,i,b,h,g,f){return d(),p("div",null,[...i[0]||(i[0]=[m('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Paramètres<br>   Paramètres moins courants</p></div><p>D&#39;autres paramètres de xDrip sont disponibles dans Paramètres moins courants.<br> Si vous ne trouvez pas le paramètre que vous cherchez, n&#39;oubliez pas que vous pouvez utiliser la loupe de recherche du menu principal des <a href="./settings.html">paramètres</a>.</p><h3 id="extra-status-line" tabindex="-1">Ligne d&#39;état supplémentaire <a class="header-anchor" href="#extra-status-line" aria-label="Permalink to &quot;Ligne d&#39;état supplémentaire {#extra-status-line}&quot;">​</a></h3><p>En haut à gauche de votre graphique principal se trouve la ligne d&#39;état standard.<br> Ce menu vous permet d&#39;ajouter des informations supplémentaires dans cette zone.</p><div class="admonition xdripitem"><p class="admonition-title">Ligne d&#39;état supplémentaire</p><p> Options pour la ligne supplémentaire</p></div><p>Vous devez activer la ligne d&#39;état supplémentaire pour ajouter des informations.</p><div class="admonition xdripitem"><p class="admonition-title">Ligne d&#39;état supplémentaire <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Statut de texte supplémentaire</p></div><p>Vous pouvez faire calculer certaines statistiques sur les dernières 24 heures. Par défaut, elles commencent à minuit.</p><div class="admonition xdripitem"><p class="admonition-title">Fenêtre coulissante <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Utilisez les dernières 24 heures au lieu de temps à partir de minuit pour les statistiques.</p></div><p>Il existe une longue liste d&#39;informations supplémentaires que vous pouvez afficher.<br> Ne sélectionnez que celles que vous avez vraiment besoin de voir toutes les 5 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Moyenne <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Valeur moyenne d’aujourd&#39;hui.</p></div><div class="admonition xdripitem"><p class="admonition-title">A1c DCCT <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Estimation du taux d’HbA1c en format DCCT (%)</p></div><div class="admonition xdripitem"><p class="admonition-title">A1c IFCC <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Estimation du taux d’HbA1c en format IFCC (mmol/mol)</p></div><div class="admonition xdripitem"><p class="admonition-title">Pourcentage Dans la plage <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Pourcentage des valeurs dans la plage.</p></div><div class="admonition xdripitem"><p class="admonition-title">Pourcentage Haut <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Pourcentage des valeurs plus haute que la plage.</p></div><div class="admonition xdripitem"><p class="admonition-title">Pourcentage Bas <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Pourcentage des valeurs inférieures à la plage.</p></div><div class="admonition xdripitem"><p class="admonition-title">Écart-type <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Voir la déviation standard des valeurs.</p></div><div class="admonition xdripitem"><p class="admonition-title">Glucides totaux <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher le total de glucides saisis par traitements</p></div><div class="admonition xdripitem"><p class="admonition-title">Insuline total <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher le total d&#39;insuline saisis par traitements</p></div><div class="admonition xdripitem"><p class="admonition-title">Statut externe <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> État de l&#39;affichage d&#39;autres applications comme AndroidAPS</p></div><div class="admonition xdripitem"><p class="admonition-title">État de la pompe <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher les informations d’état de pompe si disponible</p></div><div class="admonition xdripitem"><p class="admonition-title">Ratio Carb/Insuline <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher le ratio de carb/insuline</p></div><div class="admonition xdripitem"><p class="admonition-title">Pourcentage de capture de paquets <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Pourcentage des lectures du capteur reçus</p></div><div class="admonition xdripitem"><p class="admonition-title">Pourcentage de capture de paquets en temps réel <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Pourcentage des lectures du capteur reçues en temps réel (non récupérées). Mode Natif Dex seulement</p></div><div class="admonition xdripitem"><p class="admonition-title">Évaluation de la précision <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher l&#39;évaluation de précision de calibration des 3 derniers jours</p></div><div class="admonition xdripitem"><p class="admonition-title">Temps <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> L&#39;heure actuelle.</p></div><div class="admonition xdripitem"><p class="admonition-title">Données de calibration (long) <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Voir la pente et l&#39;ordonnée à l&#39;origine en format long.</p></div><div class="admonition xdripitem"><p class="admonition-title">Données de calibration (court) <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Voir la pente et l&#39;ordonnée à l&#39;origine en format court.</p></div><div class="admonition xdripitem"><p class="admonition-title">Plugin de Calibration <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher les données de pente et de glycémie du plugin actif</p></div><p>Vous pouvez aussi ajouter ces informations supplémentaires sur votre <a href="./mainUI.html#widget">widget</a>.</p><div class="admonition xdripitem"><p class="admonition-title">Voir sur le widget <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Afficher aussi la ligne d&#39;état supplémentaire sur le widget</p></div><h3 id="advanced-calibration" tabindex="-1"><a href="./../calibrate/advancedcal.html">Calibration avancée</a> <a class="header-anchor" href="#advanced-calibration" aria-label="Permalink to &quot;[Calibration avancée](../calibrate/advancedcal) {#advanced-calibration}&quot;">​</a></h3><p>Voir la section dédiée.</p><div class="admonition xdripitem"><p class="admonition-title">Calibration avancée</p><p> Options supplémentaires relatives aux calibrations</p></div><h3 id="bluetooth-settings" tabindex="-1"><a href="./bluetooth.html">Paramètres Bluetooth</a> <a class="header-anchor" href="#bluetooth-settings" aria-label="Permalink to &quot;[Paramètres Bluetooth](./bluetooth) {#bluetooth-settings}&quot;">​</a></h3><p>Voir la section dédiée.</p><div class="admonition xdripitem"><p class="admonition-title">Paramètres Bluetooth</p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_bluetooth_settings_grey600_48dp.png" style="width:5%;"> Paramètres Bluetooth avancés</p></div><h3 id="bluereader-settings" tabindex="-1">Paramètres blueReader <a class="header-anchor" href="#bluereader-settings" aria-label="Permalink to &quot;Paramètres blueReader {#bluereader-settings}&quot;">​</a></h3><p>Paramètres du transmetteur Libre <a href="https://www.startnext.com/en/bluereader/wall" target="_blank" rel="noreferrer">pionnier</a> conçu par Sandra.</p><div class="admonition xdripitem"><p class="admonition-title">Paramètres blueReader</p><p> Paramètres blueReader avancés</p></div><h3 id="advanced-settings-for-libre-2" tabindex="-1">Paramètres avancés pour Libre 2 <a class="header-anchor" href="#advanced-settings-for-libre-2" aria-label="Permalink to &quot;Paramètres avancés pour Libre 2 {#advanced-settings-for-libre-2}&quot;">​</a></h3><p>Affiche des informations supplémentaires pour les capteurs Libre 2</p><div class="admonition xdripitem"><p class="admonition-title">Paramètres avancés pour Libre 2</p></div><p>Afficher les valeurs brutes sur le <a href="./display.html#graph-settings">graphique principal</a></p><div class="admonition xdripitem"><p class="admonition-title">Afficher les valeurs brutes dans le graphique <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Activer pour afficher les valeurs brutes dans le graphique.</p></div><img src="'+r+'" style="zoom:75%;"><p>Afficher plus d&#39;informations dans le statut</p><div class="admonition xdripitem"><p class="admonition-title">Afficher les informations du capteur dans statut <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p><p> Activez pour afficher des informations supplémentaires du capteur de Libre 2 dans Statut.</p></div><h3 id="aggressive-service-restarts" tabindex="-1">Redémarrage du service agressif <a class="header-anchor" href="#aggressive-service-restarts" aria-label="Permalink to &quot;Redémarrage du service agressif {#aggressive-service-restarts}&quot;">​</a></h3><p>Activer cette option provoque un <a href="./../troubleshoot/systemstatus.html#restart-collector-forget-device">redémarrage du collecteur</a> lorsque des données manquantes sont détectées. Cela peut être utile si vous avez des problèmes de connexion.</p><div class="admonition xdripitem"><p class="admonition-title">Redémarrage du service agressif <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Redémarrer constamment le service de collecte en cas de soupçon de données manquantes. Activer uniquement si vous observez des pertes de données.</p></div><h3 id="interpret-raw-values" tabindex="-1">Interpréter les valeurs brutes <a class="header-anchor" href="#interpret-raw-values" aria-label="Permalink to &quot;Interpréter les valeurs brutes {#interpret-raw-values}&quot;">​</a></h3><p>Affiche les données lorsqu&#39;elles ne sont pas disponibles sur le récepteur Dexcom.</p><div class="admonition xdripitem"><p class="admonition-title">Interpréter les valeurs brutes <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Si vous utilisez Share, xDrip affichera les valeurs quand elles sont normalement cachées sur le récepteur.</p></div><h3 id="extra-logging-settings" tabindex="-1">Paramètres de logs supplémentaires <a class="header-anchor" href="#extra-logging-settings" aria-label="Permalink to &quot;Paramètres de logs supplémentaires {#extra-logging-settings}&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Paramètres de logs supplémentaires</p></div><p>Ces options ne sont plus utilisées.</p><div class="admonition xdripitem"><p class="admonition-title">Activer la journalisation à distance <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Stocker les journaux pour le dépannage <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>Ajouter des balises supplémentaires est utile pour le débogage, car cela ajoute des traces spécifiques dans le journal.</p><div class="admonition xdripitem"><p class="admonition-title">Balises supplémentaires pour le log</p></div><p>Vous devez savoir ce que vous voulez déboguer et régler le bon niveau. Veillez à saisir des balises valides pour éviter que xDrip ne plante.</p><img src="'+o+'" style="zoom:75%;"><h3 id="show-data-tables" tabindex="-1">Afficher les tables de données <a class="header-anchor" href="#show-data-tables" aria-label="Permalink to &quot;Afficher les tables de données {#show-data-tables}&quot;">​</a></h3><p>Cette fonction est extrêmement utile si vous étalonnez avec l&#39;algorithme de xDrip (non natif).<br> Elle ajoute deux entrées dans le menu latéral pour visualiser les tables d&#39;étalonnage et de données.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher les tables de données <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Afficher les données de calibrations et de glycémies dans le menu applicatif.</p></div><p><em>Remarque : le graphique d&#39;étalonnage ne s&#39;affiche pas en mode natif.</em></p><h3 id="display-bridge-battery" tabindex="-1">Afficher la batterie du transmetteur <a class="header-anchor" href="#display-bridge-battery" aria-label="Permalink to &quot;Afficher la batterie du transmetteur {#display-bridge-battery}&quot;">​</a></h3><p>Vous pouvez afficher le niveau de batterie de votre transmetteur Bluetooth sur l&#39;écran principal. Cela s&#39;applique aussi aux transmetteurs Bluetooth Libre.<br> En mode abonné, c&#39;est très probablement le niveau de batterie du téléphone principal qui s&#39;affichera plutôt que celui du transmetteur.</p><div class="admonition xdripitem"><p class="admonition-title">Afficher la batterie du transmetteur <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Choisir pour afficher le niveau de batterie du transmetteur</p></div><img src="'+n+'" style="zoom:75%;"><h3 id="disable-battery-warning" tabindex="-1">Désactiver l&#39;avertissement de batterie <a class="header-anchor" href="#disable-battery-warning" aria-label="Permalink to &quot;Désactiver l&#39;avertissement de batterie {#disable-battery-warning}&quot;">​</a></h3><p>Désactive les avertissements de batterie des transmetteurs</p><div class="admonition xdripitem"><p class="admonition-title">Désactiver l&#39;avertissement de batterie <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Désactiver l’avertissement de l’état pile faible des émetteurs sur l’écran d’accueil. (Uniquement valable pour les récepteurs DIY)</p></div><h3 id="database-automatic-maintenance" tabindex="-1">Maintenance automatique de la base de données <a class="header-anchor" href="#database-automatic-maintenance" aria-label="Permalink to &quot;Maintenance automatique de la base de données {#database-automatic-maintenance}&quot;">​</a></h3><p>Enregistrer la base de données tous les jours exporte réellement le fichier de base de données chaque jour avant le nettoyage. Cela occupe beaucoup de mémoire sur votre appareil et n&#39;est pas recommandé.</p><p>Les exports de la base de données sont enregistrés dans le même dossier que les exports manuels : <code>/storage/emulated/0/xDrip</code> ou <code>Internal Storage/xDrip</code>.</p><div class="admonition xdripitem"><p class="admonition-title">Enregistrer la base de données tous les jours <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Permet au Service d’intention quotidienne de sauvegarder la base de données avant la purge</p></div><h4 id="glucose-retention" tabindex="-1">Rétention des glycémies <a class="header-anchor" href="#glucose-retention" aria-label="Permalink to &quot;Rétention des glycémies {#glucose-retention}&quot;">​</a></h4><p>Rétention des glycémies supprime automatiquement les données plus anciennes que le nombre de jours choisi.<br> Zéro signifie ne rien supprimer. La valeur par défaut est de 180 jours : une nouvelle installation supprime donc automatiquement les données de plus de 180 jours, sauf si vous modifiez ce réglage. Vous pouvez choisir 90 jours si vous utilisez une sauvegarde dans le cloud comme Nightscout, tout en gardant toutes les statistiques disponibles dans xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Rétention des glycémies</p><p> Effacer les données antérieures à ce nombre de jours. 0 = ne rien effacer</p></div><h3 id="other-miscellaneous-options" tabindex="-1"><a href="./misc.html">Autres options diverses</a> <a class="header-anchor" href="#other-miscellaneous-options" aria-label="Permalink to &quot;[Autres options diverses](./misc) {#other-miscellaneous-options}&quot;">​</a></h3><p>Voir la section dédiée.</p><div class="admonition xdripitem"><p class="admonition-title">Autres options diverses</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',86)])])}const D=l(c,[["render",u]]);export{A as __pageData,D as default};
